module TopModule (
    input wire c,
    input wire d,
    output reg [3:0] mux_in
);

    // Internal signals for 2-to-1 multiplexers
    wire a;
    wire b;

    // Assigning values to a and b based on c and d
    assign a = c & ~d;  // a = 0 when c=0 or d=1
    assign b = c & d;   // b = 1 when c=1 and d=1

    // 4-to-1 multiplexer using 2-to-1 multiplexers
