module TopModule (
    input  wire clk,
    input  wire areset,
    input  wire in,
    output reg out
);

    // State definition
    typedef enum logic {A, B} state_t;

    // Register to hold the current state
    state_t currentState, nextState;

    // Asynchronous reset
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            currentState <= B;
        else
            currentState <= nextState;
    end

    // Synchronous block to update next state based on current state and input
    always_comb begin
        case (currentState)
            A: 
                if (in == 1'b0)
                    nextState = B;
                else
                    nextState = A;
            B:
                if (in == 1'b0)
                    nextState = A;
                else
                    nextState = B;
            default:
                nextState = B; // Default to state B
        endcase
    end

    // Output logic
    always_comb begin
        out = (currentState == A);
    end

endmodule

