module TopModule (
    input wire clk,
    input wire reset,
    output reg shift_ena
);

reg [1:0] state;
parameter IDLE = 2'b00;
parameter ENABLE_1 = 2'b01;
parameter ENABLE_2 = 2'b10;
parameter ENABLE_3 = 2'b11;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
        shift_ena <= 1;
    end else begin
        case (state)
            IDLE: begin
                shift_ena <= 1;
                if (shift_ena == 0 && reset == 0) begin // Wait until reset is de-asserted
                    state <= ENABLE_1;
                end
            end
            ENABLE_1: begin
                shift_ena <= 1;
                state <= ENABLE_2;
            end
            ENABLE_2: begin
                shift_ena <= 1;
                state <= ENABLE_3;
            end
            ENABLE_3: begin
                shift_ena <= 1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

