module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    typedef enum reg [1:0] {A, B} state_t;
    state_t current_state, next_state;
    reg [2:0] w_counter;

    always @(posedge clk or posedge reset) begin
        if (reset)
            begin
                current_state <= A;
                z <= 0;
            end
        else
            begin
                current_state <= next_state;
                if (current_state == B && w_counter == 3'b010 || w_counter == 3'b101 || w_counter == 3'b110)
                    z <= 1;
                else
                    z <= 0;
            end
    end

    always @(*) begin
        case(current_state)
            A:
                if (s)
                    next_state = B;
                else
                    next_state = A;
            B:
                next_state = B;
            default:
                next_state = A;
        endcase
    end

    always @(posedge clk or posedge reset) begin
        if (reset)
            w_counter <= 3'b000;
        else
            begin
                if (current_state == B)
                    w_counter <= w ? w_counter + 1 : w_counter - 1;
            end
    end

endmodule

module TopModule (
    input wire clk,
    input wire areset,
    input wire in,
    output reg out
);

// Define states
typedef enum reg [1:0] {
    STATE_A = 2'b00,
    STATE_B = 2'b01,
    STATE_C = 2'b10,
    STATE_D = 2'b11
} state_t;

// Current state register
reg [1:0] currentState;
// Next state register
reg [1:0] nextState;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        currentState <= STATE_A; // Reset to state A
    end else begin
        currentState <= nextState; // Update to next state
    end
end

// State transition logic
always @(*) begin
    case (currentState)
        STATE_A: 
            if (in == 0) nextState = STATE_A;
            else          nextState = STATE_B;
        STATE_B:
            if (in == 0) nextState = STATE_B;
            else          nextState = STATE_B;
        STATE_C:
            if (in == 0) nextState = STATE_A;
            else          nextState = STATE_D;
        STATE_D:
            if (in == 0) nextState = STATE_C;
            else          nextState = STATE_B;
        default: nextState = STATE_A; // Default to state A
    endcase
end

// Output logic
always @(*) begin
    case (currentState)
        STATE_A: out = 0;
        STATE_B: out = 0;
        STATE_C: out = 0;
        STATE_D: out = 1;
        default: out = 0; // Default output
    endcase
end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  in,
    output reg done
);

    typedef enum {IDLE, START, DATA, STOP} state_t;
    state_t state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (in == 0) begin
                        state <= START;
                    end
                end
                START: begin
                    if (in == 0) begin
                        state <= DATA;
                    end
                end
                DATA: begin
                    if (in != 0) begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    if (in == 1) begin
                        state <= IDLE;
                        done <= 1;
                    end
                end
            endcase
        end
    end

endmodule

