module TopModule (
    input wire clk,
    input wire resetn,
    input wire [2:0] r,
    output reg [2:0] g
);

// State definitions
localparam [1:0] STATE_A = 2'b00;
localparam [1:0] STATE_B = 2'b01;
localparam [1:0] STATE_C = 2'b10;
localparam [1:0] STATE_D = 2'b11;

// Current state register
reg [1:0] currentState;

// Next state logic
always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        currentState <= STATE_A;
    end else begin
        case (currentState)
            STATE_A: begin
                if ((r == 3'b000) && (currentState != STATE_D)) begin
                    currentState <= STATE_A;
                end else if (r[0]) begin
                    currentState <= STATE_B;
                end else if ((r[1]) && !(r[0])) begin
                    currentState <= STATE_C;
                end else if ((r == 3'b000) && (currentState == STATE_D)) begin
                    currentState <= STATE_A;
                end else begin
                    currentState <= STATE_D;
                end
            end
            STATE_B: begin
                if (r[0]) begin
                    currentState <= STATE_B;
                end else begin
                    currentState <= STATE_A;
                end
            end
            STATE_C: begin
                if (r[1]) begin
                    currentState <= STATE_C;
                end else begin
                    currentState <= STATE_A;
                end
            end
            default: currentState <= STATE_A; // Default to state A
        endcase
    end
end

// Output logic based on current state
always @(*) begin
    g = 3'b000;
    case (currentState)
        STATE_A: begin
            if ((r[0] || r[1] || r[2])) begin
                if (r[0]) begin
                    g[0] = 1'b1;
                end else if (r[1]) begin
                    g[1] = 1'b1;
                end else if (r[2]) begin
                    g[2] = 1'b1;
                end
            end
        end
        STATE_B: begin
            g[0] = 1'b1;
        end
        STATE_C: begin
            g[1] = 1'b1;
        end
        default: begin
            g = 3'b000;
        end
    endcase
end

endmodule

