  input areset, 
  input bump_left, 
  input bump_right, 
  input ground, 
  input dig, 
  output reg walk_left, 
  output reg walk_right, 
  output reg aaah, 
  output reg digging); 
  parameter S_WALK_LEFT = 3'b000; 
  parameter S_WALK_RIGHT = 3'b001; 
  parameter S_FALLING = 3'b010; 
  parameter S_DIGGING = 3'b011; 
  parameter S_WAIT_FOR_GROUND = 3'b100; 
  reg [2:0] present_state, next_state; 
  always @(posedge clk) begin 
  if(areset) begin 
  present_state <= S_WALK_LEFT; 
  end else begin 
  present_state <= next_state; 
  end 
  end 
  always @(*) begin 
  case(present_state) 
  S_WALK_LEFT: begin 
  if(~dig & ~ground) begin 
  next_state = S_FALLING; 
  end else if(dig & ground) begin 
  next_state = S_DIGGING; 
  end else if(bump_left | bump_right) begin 
  next_state = (bump_left)?S_WALK_RIGHT:S_WALK_LEFT; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  S_WALK_RIGHT: begin 
  if(~dig & ~ground) begin 
  next_state = S_FALLING; 
  end else if(dig & ground) begin 
  next_state = S_DIGGING; 
  end else if(bump_left | bump_right) begin 
  next_state = (bump_right)?S_WALK_LEFT:S_WALK_RIGHT; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  S_FALLING: begin 
  if(~ground) begin 
  next_state = S_FALLING; 
  end else if(~dig) begin 
  next_state = S_WAIT_FOR_GROUND; 
  end else if(dig) begin 
  next_state = S_DIGGING; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  S_WAIT_FOR_GROUND: begin 
  if(~dig & ground) begin 
  next_state = S_WALK_LEFT; 
  end else if(~dig & ~ground) begin 
  next_state = S_FALLING; 
  end else if(dig & ground) begin 
  next_state = S_DIGGING; 
  end else if(dig & ~ground) begin 
  next_state = S_WAIT_FOR_GROUND; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  S_DIGGING: begin 
  if(~dig & ~ground) begin 
  next_state = S_FALLING; 
  end else if(~dig & ground) begin 
  next_state = S_WALK_LEFT; 
  end else if(dig & ~ground) begin 
  next_state = S_DIGGING; 
  end else if(dig & ground) begin 
  next_state = S_DIGGING; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  default: begin 
  next_state = present_state; 
  end 
  endcase 
  end 
  always @(posedge clk) begin 
  case(next_state) 
  S_WALK_LEFT: begin 
  walk_left <= 1'b1; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  S_WALK_RIGHT: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b1; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  S_FALLING: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b1; 
  digging <= 1'b0; 
  end 
  S_DIGGING: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b1; 
  end 
  S_WAIT_FOR_GROUND: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  default: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  endcase 
  end 
  endmodule
